const incoming = $input.first().json;
let data = incoming.body ?? incoming;
if (typeof data === 'string') {
  try { data = JSON.parse(data); } catch { throw new Error('Request body must be valid JSON'); }
}
const clean = value => String(value ?? '').trim();
const escapeHtml = value => clean(value).replace(/[&<>\"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[char]));
const name = clean(data.name).slice(0, 100);
const email = clean(data.email).slice(0, 254).toLowerCase();
const phone = clean(data.phone).slice(0, 25);
const service = clean(data.service).slice(0, 100);
const date = clean(data.date).slice(0, 10);
const time = clean(data.time).slice(0, 60);
const note = clean(data.message).slice(0, 500);
if (clean(data.company)) throw new Error('Invalid form submission');
if (!name || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || !phone || !/^\d{4}-\d{2}-\d{2}$/.test(date) || !service || !time) {
  throw new Error('Please provide a valid name, email, phone, service, date, and time');
}
const safeName = escapeHtml(name);
const safeEmail = escapeHtml(email);
const safePhone = escapeHtml(phone);
const safeService = escapeHtml(service);
const safeDate = escapeHtml(date);
const safeTime = escapeHtml(time);
const safeNote = escapeHtml(note).replace(/\r?\n/g, '<br>') || 'No additional note';
const details = `<table role="presentation" style="width:100%;border-collapse:collapse"><tr><td style="padding:10px;border-bottom:1px solid #e6e8eb"><b>Name</b></td><td style="padding:10px;border-bottom:1px solid #e6e8eb">${safeName}</td></tr><tr><td style="padding:10px;border-bottom:1px solid #e6e8eb"><b>Email</b></td><td style="padding:10px;border-bottom:1px solid #e6e8eb">${safeEmail}</td></tr><tr><td style="padding:10px;border-bottom:1px solid #e6e8eb"><b>Phone</b></td><td style="padding:10px;border-bottom:1px solid #e6e8eb">${safePhone}</td></tr><tr><td style="padding:10px;border-bottom:1px solid #e6e8eb"><b>Requested service</b></td><td style="padding:10px;border-bottom:1px solid #e6e8eb">${safeService}</td></tr><tr><td style="padding:10px;border-bottom:1px solid #e6e8eb"><b>Preferred date</b></td><td style="padding:10px;border-bottom:1px solid #e6e8eb">${safeDate}</td></tr><tr><td style="padding:10px;border-bottom:1px solid #e6e8eb"><b>Preferred time</b></td><td style="padding:10px;border-bottom:1px solid #e6e8eb">${safeTime}</td></tr><tr><td style="padding:10px"><b>Note</b></td><td style="padding:10px">${safeNote}</td></tr></table>`;
const shell = body => `<div style="font-family:Arial,sans-serif;color:#263638;line-height:1.6;max-width:620px;margin:0 auto;padding:28px"><div style="font-size:23px;font-weight:700;color:#176a65;margin-bottom:20px">Dentora</div>${body}<p style="margin-top:28px;color:#697778;font-size:13px">Dentora Dental Care · Please reply to this email if you have any questions.</p></div>`;
const adminHtml = shell(`<h2 style="font-size:21px">New appointment request</h2><p>A patient has sent an appointment request. Please contact them to confirm availability.</p>${details}`);
const patientHtml = shell(`<h2 style="font-size:21px">We received your request, ${safeName}.</h2><p>Thank you for contacting Dentora. Your appointment request is with our team. This email confirms receipt only; your appointment is not booked until the clinic confirms a time with you.</p><h3 style="font-size:16px">Your requested visit</h3>${details}<p>Our team will follow up using the contact details you provided.</p>`);
return [{ json: { name, email, phone, service, date, time, message: note, adminHtml, patientHtml } }];
